function sanitize(s) {
  if (s == null) return '';
  let t = String(s);
  t = t.replace(/[\r\n\t]+/g, ' ');
  t = t.replace(/[`<>{}|\\$]/g, '');
  t = t.replace(/\b(ignore|disregard|system|assistant|prompt|instruction)\b/gi, '_');
  t = t.replace(/\s+/g, ' ').trim();
  t = t.replace(/signal-key\s*:/gi, 'signal-key_');
  if (t.length > 140) t = t.slice(0, 140) + String.fromCharCode(8230);
  return t;
}
// AIR-230 · Recencia/era + plantilla accionable.
// A#2/A#3: solo cuentan fallos RECIENTES (stoppedAt dentro de N_DIAS), no el acumulado de las ultimas 100.
const N_DIAS = 3;
const ahora = Date.now();
const ventanaMs = N_DIAS * 86400000;
// Errores (includeData=true) = input directo de este nodo.
const rows = $input.first().json.data || [];
// A#1: todas las ejecuciones (todos los estados, includeData=false) para saber si el workflow YA se recupero.
const todas = ($('n8n - Ejecuciones recientes (todas)').first().json.data) || [];
// Mapa workflowId -> ejecucion automatica mas reciente { at, status }.
const ultimaPorWf = {};
for (const e of todas) {
  if (e.mode !== 'trigger' && e.mode !== 'webhook') continue; // solo disparos automaticos
  const at = e.stoppedAt || e.startedAt || null;
  if (!at) continue;
  const prev = ultimaPorWf[e.workflowId];
  if (!prev || at > prev.at) {
    let st = e.status;
    if (!st) st = e.finished ? 'success' : 'unknown';
    ultimaPorWf[e.workflowId] = { at: at, status: st };
  }
}
const byWf = {};
for (const r of rows) {
  // (1) AIR-225 auto-monitoreo: el Sentinela NO se auto-excluye de la deteccion historica de sus propios fallos.
  //     La de-exclusion del self convive con la recencia (A#4): un fallo REPETIDO y RECIENTE del propio Sentinela
  //     si genera issue; el dedupe por signal-key evita duplicados y el auto-cierre lo cierra al recuperarse.
  if (r.mode !== 'trigger' && r.mode !== 'webhook') continue; // (2) allowlist: solo disparos automaticos (excluye manual)
  if (!(r.data && r.data.resultData && r.data.resultData.error && r.data.resultData.error.message)) continue; // (3) requiere error real (includeData=true)
  const at = r.stoppedAt || r.startedAt || null;
  if (!at) continue;
  // A#2 recencia real: descartar fallos fuera de la ventana de N_DIAS.
  const atMs = Date.parse(at);
  if (!(atMs > 0) || (ahora - atMs) > ventanaMs) continue;
  const name = (r.workflowData && r.workflowData.name) || r.workflowId || 'desconocido';
  if (!byWf[name]) byWf[name] = { count: 0, wfId: r.workflowId || '', lastErr: null, lastAt: null, lastExecId: null, lastNode: null, firstAt: null, isWebhook: false };
  const g = byWf[name];
  g.count += 1;
  if (r.mode === 'webhook') g.isWebhook = true;
  if (!g.firstAt || at < g.firstAt) g.firstAt = at;
  if (!g.lastAt || at > g.lastAt) {
    g.lastAt = at;
    const err = r.data.resultData.error;
    // B#6: el mensaje accionable esta en description/messages[0], no en el generico message.
    g.lastErr = err.description || (err.messages && err.messages[0]) || err.message || '';
    g.lastNode = (err.node && err.node.name) || '';
    g.lastExecId = r.id || '';
    g.wfId = r.workflowId || g.wfId;
  }
}
const out = [];
for (const name of Object.keys(byWf)) {
  const g = byWf[name];
  if (g.count < 2) continue; // A#3 umbral por recurrencia RECIENTE (no acumulado historico)
  // A#1: si la ejecucion automatica mas reciente del workflow es success, ya se recupero -> suprimir la senal.
  const ult = ultimaPorWf[g.wfId];
  if (ult && ult.status === 'success') continue;
  const safeName = sanitize(name);
  const safeErr = sanitize(g.lastErr) || 'sin mensaje';
  const safeNode = sanitize(g.lastNode) || 'desconocido';
  const signalKey = 'n8n_exec_fail:' + safeName;
  const titulo = (safeName + ' fallo ' + g.count + ' veces: ' + safeErr).slice(0, 200);
  // B#5: link directo a la ultima ejecucion fallida.
  const link = (g.wfId && g.lastExecId)
    ? 'https://airedeagua.app.n8n.cloud/workflow/' + g.wfId + '/executions/' + g.lastExecId
    : 'https://airedeagua.app.n8n.cloud/home/executions';
  // B#8: prioridad por severidad. Webhook productivo caido -> 1 (Urgent); >=5 fallos -> 2 (High); resto -> 3 (Medium).
  let priority = 3;
  if (g.count >= 5) priority = 2;
  if (g.isWebhook) priority = 1;
  const descripcion = 'Señal automática (Sentinela v1): el workflow n8n **' + safeName + '** registró ' + g.count + ' ejecuciones con estado error en los últimos ' + N_DIAS + ' días.\n\n' +
    'Nodo que falló: ' + safeNode + '\n' +
    'Último error (saneado): ' + safeErr + '\n' +
    'Primer fallo: ' + (g.firstAt || 'n/d') + '\n' +
    'Último fallo: ' + (g.lastAt || 'n/d') + '\n' +
    'Ejecución: ' + link + '\n\n' +
    'Nivel de autonomía: pr-only (máximo).\n\nsignal-key: ' + signalKey;
  out.push({ json: {
    senal: 'n8n_exec_fail',
    fuente: safeName,
    signalKey: signalKey,
    titulo: titulo,
    descripcion: descripcion,
    priority: priority,
  } });
}
return out;

function sanitize(s) {
