function normName(name) {
  return String(name || '').trim().replace(/[^a-zA-Z0-9_\- ]/g, '').replace(/[\s-]+/g, '_');
}
const BASELINE = $vars && $vars.SENTINELA_BASELINE ? JSON.parse($vars.SENTINELA_BASELINE) : null;
const list = $input.first().json.data || [];
const liveNames = list.filter(function (w) { return w.active; }).map(function (w) { return normName(w.name); });
const out = [];
if (!BASELINE) {
  return out;
}
const baseSet = new Set(BASELINE);
for (const n of liveNames) {
  if (!baseSet.has(n)) {
    const safe = sanitize(n);
    const signalKey = 'drift:' + safe;
    out.push({ json: {
      senal: 'drift',
      fuente: safe,
      signalKey: signalKey,
      titulo: ("Workflow " + safe + " divergió del JSON versionado").slice(0, 200),
      descripcion: 'Senal automatica (Sentinela v1): el workflow activo **' + safe + '** existe en n8n pero no aparece en el baseline versionado (n8n/workflows/). Drift de GitOps: exporta y commitea, o desactiva el workflow.\n\nNivel de autonomia: pr-only.\n\nsignal-key: ' + signalKey,
    } });
  }
}
return out;

// Label IDs (team AIR). NUNCA usar agent-ready (c89c500f-...) en señales de Sentinela: es pr-only.
const LBL_NEEDS_REFINEMENT = '197fb5ae-dff3-45de-b2ae-1533069d1d39';
const LBL_SENSORS = 'd30a9e60-b290-4fd4-bacc-c9c87d66bf18';
// AIR-225: provenance. TODA señal de Sentinela nace con el label 'sentinela'.
// Es el candado del auto-cierre: solo issues con este label (+ marcador signal-key) son elegibles para cerrarse.
const LBL_SENTINELA = '519560f6-81b5-4f06-b5b8-29c50813bb09';
// AIR-248: human-gate. draft_unpublished se arregla con un publish_workflow humano (no codigo) -> jamas agent-ready ni needs-refinement.
const LBL_HUMAN_GATE = '5ecc352a-e16d-4768-935f-133ae389a9dd';
// Labels por tipo de señal (sentinela SIEMPRE presente):
//   n8n_exec_fail / drift -> [sentinela, needs-refinement]
//   sync_gap              -> [sentinela, Sensors, needs-refinement] (jamás agent-ready)
//   draft_unpublished     -> [sentinela, human-gate] (paso humano; ni agent-ready ni needs-refinement)
function labelsFor(senal) {
  if (senal === 'sync_gap') return [LBL_SENTINELA, LBL_SENSORS, LBL_NEEDS_REFINEMENT];
  if (senal === 'draft_unpublished') return [LBL_SENTINELA, LBL_HUMAN_GATE];
  return [LBL_SENTINELA, LBL_NEEDS_REFINEMENT];
}
const ctx = $("Linear - Contexto (label + abiertos)").first().json;
const gql = (ctx && ctx.data) || {};
const abiertos = (gql.issues && gql.issues.nodes) || [];
const keysAbiertos = new Set();
for (const i of abiertos) {
  const m = String(i.description || '').match(/signal-key:\s*([^\n\r]+)/);
  if (m && m[1]) keysAbiertos.add(m[1].trim());
}
const candidatos = $input.all().map(function (i) { return i.json; });
const vistos = new Set();
const out = [];
for (const c of candidatos) {
  const t = String(c.titulo || '').trim();
  if (!t) continue;
  const sk = String(c.signalKey || '').trim();
  if (!sk) continue;
  if (keysAbiertos.has(sk)) continue;
  if (vistos.has(sk)) continue;
  vistos.add(sk);
  const senal = c.senal || '';
  // AIR-230 B: threading de priority hasta el IssueCreateInput. exec_fail lo trae (1/2/3);
  // sync_gap/drift/draft_unpublished no lo setean -> 3 (Medium) por defecto (nunca None).
  const priority = (typeof c.priority === 'number' && c.priority >= 1 && c.priority <= 4) ? c.priority : 3;
  out.push({ json: {
    titulo: t,
    descripcion: c.descripcion || '',
    senal: senal,
    fuente: c.fuente || '',
    signalKey: sk,
    labelIds: labelsFor(senal),
    priority: priority,
  } });
}
return out;

