// AIR-225 auto-cierre (absorbe AIR-121). Candados de seguridad DUROS: se cierra un issue SOLO si
// (1) su cuerpo trae el marcador signal-key, (2) lleva el label sentinela, y (3) su senal ya NO esta
// viva en esta corrida (exitosa). NUNCA se toca un issue humano. El texto externo (description) solo se
// REGEX-matchea para extraer la clave; jamas se interpreta como instruccion. sanitize() se preserva por
// invariante anti prompt-injection.
const SENTINELA_LABEL_ID = '519560f6-81b5-4f06-b5b8-29c50813bb09';
const SENTINELA_LABEL_NAME = 'sentinela';
// $input = merge [senales vivas de "Unir candidatos"  +  item de contexto de "Linear - Contexto"].
// El item de contexto garantiza >=1 item de entrada => este nodo SIEMPRE corre (incluso con 0 senales
// vivas: en ese caso se cierran todas las senales resueltas). Corre despues del merge => tras todas las
// ramas de deteccion, por lo que el set de vivos esta completo.
const items = $input.all().map(function (i) { return i.json; });
const vivos = new Set();
let ctxItem = null;
for (const it of items) {
  if (it && it.signalKey) vivos.add(String(it.signalKey).trim());
  if (it && it.data && it.data.issues) ctxItem = it;
}
let abiertos = [];
if (ctxItem && ctxItem.data && ctxItem.data.issues && ctxItem.data.issues.nodes) {
  abiertos = ctxItem.data.issues.nodes;
} else {
  const ctx = $("Linear - Contexto (label + abiertos)").first().json;
  abiertos = (ctx && ctx.data && ctx.data.issues && ctx.data.issues.nodes) || [];
}
const out = [];
for (const issue of abiertos) {
  const m = String(issue.description || '').match(/signal-key:\s*([^\n\r]+)/);
  if (!m || !m[1]) continue;              // CANDADO 1: marcador signal-key
  const sk = m[1].trim();
  if (!sk) continue;
  const labs = (issue.labels && issue.labels.nodes) || [];
  const esSentinela = labs.some(function (l) { return l && (l.id === SENTINELA_LABEL_ID || l.name === SENTINELA_LABEL_NAME); });
  if (!esSentinela) continue;             // CANDADO 2: label sentinela (jamas issues humanos)
  if (vivos.has(sk)) continue;            // CANDADO 3: la senal sigue viva => no cerrar
  out.push({ json: { issueId: String(issue.id || ''), identifier: sanitize(issue.identifier), signalKey: sanitize(sk) } });
}
return out;

