// AIR-248 · Senal draft_unpublished: workflows con draft sin publicar.
// n8n EJECUTA activeVersion.nodes (lo PUBLICADO), no el draft. Un fix mergeado que quedo solo en
// draft (versionId != activeVersionId) NO esta vivo en produccion hasta hacer publish (paso humano).
// Reusa la salida YA fetchada por 'n8n - Workflows actuales' (GET /api/v1/workflows trae versionId Y activeVersionId).
const list = ($('n8n - Workflows actuales').first().json.data) || [];
const out = [];
for (const w of list) {
  // Filtro anti-falso-positivo OBLIGATORIO: solo workflows ACTIVOS con activeVersionId presente y draft != publicado.
  // Los ~29 workflows inactivos traen activeVersionId:null -> nunca publicados / no aplica -> se excluyen aqui.
  if (!(w.active === true && w.activeVersionId && w.versionId !== w.activeVersionId)) continue;
  const wfId = String(w.id || '');
  const safe = sanitize(w.name) || wfId || 'desconocido';
  // signalKey por ID del workflow (estable ante renames), NO por nombre.
  const signalKey = 'draft_unpublished:' + wfId;
  const titulo = ('Workflow ' + safe + ' tiene un draft sin publicar').slice(0, 200);
  const descripcion = 'Senal automatica (Sentinela v1): el workflow n8n **' + safe + '** (id ' + wfId + ') tiene un draft sin publicar. ' +
    'n8n ejecuta la version ACTIVA (activeVersion.nodes), no el draft: un fix ya guardado en el draft NO esta vivo en produccion hasta publicar.\n\n' +
    'versionId (draft): ' + sanitize(w.versionId) + '\n' +
    'activeVersionId (vivo): ' + sanitize(w.activeVersionId) + '\n\n' +
    'Fix (paso HUMANO): publish_workflow ' + wfId + ' -- publicar el draft para que la version activa quede igual al draft. No es codigo; requiere accion humana (por eso el label human-gate, no agent-ready).\n\n' +
    'Nivel de autonomia: pr-only (maximo).\n\nsignal-key: ' + signalKey;
  out.push({ json: {
    senal: 'draft_unpublished',
    fuente: safe,
    signalKey: signalKey,
    titulo: titulo,
    descripcion: descripcion,
  } });
}
return out;
